# Resolve the real script path across ConsoleHost, PowerShell ISE and editor-run contexts.
function Test-AMRAdmin {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($identity)
    return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

$amrNeedsSta = ([System.Threading.Thread]::CurrentThread.GetApartmentState() -ne 'STA')
$amrNeedsAdmin = -not (Test-AMRAdmin)
$amrIsIseHost = ($Host.Name -match 'ISE')
$amrScriptPath = ''

# First use PowerShell's invocation metadata (works for normal -File launches).
try {
    $amrCandidates = @([string]$PSCommandPath, [string]$MyInvocation.MyCommand.Path, [string]$MyInvocation.PSCommandPath)
    foreach ($amrCandidate in $amrCandidates) {
        if (-not [string]::IsNullOrWhiteSpace($amrCandidate) -and (Test-Path -LiteralPath $amrCandidate -PathType Leaf)) {
            $amrScriptPath = (Resolve-Path -LiteralPath $amrCandidate).Path
            break
        }
    }
} catch { }

# ISE can expose the open editor's path even when invocation metadata is empty.
if ($amrIsIseHost -and [string]::IsNullOrWhiteSpace($amrScriptPath)) {
    try {
        if ($psISE -and $psISE.CurrentFile) {
            $amrIsePath = [string]$psISE.CurrentFile.FullPath
            if (-not [string]::IsNullOrWhiteSpace($amrIsePath) -and (Test-Path -LiteralPath $amrIsePath -PathType Leaf)) {
                $amrScriptPath = (Resolve-Path -LiteralPath $amrIsePath).Path
            }
        }
    } catch { }
}

# If ISE is executing an unsaved editor buffer, persist that exact buffer to a
# temporary .ps1 so it can be relaunched elevated in a separate process.
if ($amrIsIseHost -and [string]::IsNullOrWhiteSpace($amrScriptPath)) {
    try {
        $amrEditorText = [string]$psISE.CurrentFile.Editor.Text
        if (-not [string]::IsNullOrWhiteSpace($amrEditorText)) {
            $amrTempName = 'AMR_Utility_ISE_{0}.ps1' -f ([guid]::NewGuid().ToString('N'))
            $amrScriptPath = Join-Path $env:TEMP $amrTempName
            [System.IO.File]::WriteAllText($amrScriptPath, $amrEditorText, (New-Object System.Text.UTF8Encoding($true)))
        }
    } catch {
        $amrScriptPath = ''
    }
}

# ISE owns its process identity and taskbar button. Run the utility in its own
# Windows PowerShell process so AMR can use its own window/taskbar identity.
if ($amrNeedsSta -or $amrNeedsAdmin -or $amrIsIseHost) {
    if (-not [string]::IsNullOrWhiteSpace($amrScriptPath) -and (Test-Path -LiteralPath $amrScriptPath -PathType Leaf)) {
        $amrQuotedScriptPath = '"' + $amrScriptPath.Replace('"','""') + '"'
        $amrStartArgumentLine = '-NoProfile -ExecutionPolicy Bypass -STA -File ' + $amrQuotedScriptPath
        $amrStartParams = @{ FilePath='powershell.exe'; ArgumentList=$amrStartArgumentLine; WindowStyle='Hidden'; ErrorAction='Stop' }
        if ($amrNeedsAdmin) { $amrStartParams.Verb = 'RunAs' }
        try { Start-Process @amrStartParams }
        catch {
            if ($amrNeedsAdmin) { throw ('Administrator launch was cancelled or failed: ' + $_.Exception.Message) }
            throw ('Could not start the required STA PowerShell host: ' + $_.Exception.Message)
        }
        exit
    }
    if ($amrIsIseHost) {
        throw 'AMR Utility could not read the current PowerShell ISE editor buffer. Save the script as a .ps1 file, then press F5 again.'
    }
    if ($amrNeedsSta) {
        throw 'AMR Utility requires an STA PowerShell host. Run the saved .ps1 file with Windows PowerShell.'
    }
    throw 'AMR Utility needs administrator permissions, but PowerShell did not provide a valid script file path. Save the script as a .ps1 file and launch it with Windows PowerShell.'
}

