                    }
                    if ($infCandidates.Count -gt 0) {
                        $bestInfCandidate = $infCandidates | Sort-Object @{Expression={$_.MatchRank};Ascending=$true},@{Expression={$_.MatchIndex};Ascending=$true},@{Expression={$_.MatchLength};Descending=$true},@{Expression={$_.FileName};Ascending=$true} | Select-Object -First 1
                        $localInstallableInfFiles = @([string]$bestInfCandidate.RelativePath)
                    }
                    if (@($localInstallableInfFiles).Count -eq 0) { throw 'No INF matched the selected device with a valid signed catalog. AMR will use the Windows Update installation path instead.' }
                    $expandedFiles = @(Get-ChildItem -LiteralPath $inspectionRoot -File -Recurse -ErrorAction Stop | ForEach-Object {
                        [pscustomobject]@{
                            RelativePath=$_.FullName.Substring($inspectionRoot.Length).TrimStart('\\')
                            SizeBytes=[int64]$_.Length
                            SHA256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256 -ErrorAction Stop).Hash
                        }
                    })
                    if ($expandedFiles.Count -lt 1) { throw 'The prepared driver package contains no extracted files to inventory.' }
                    $manifest = [pscustomobject]@{
                        Product='AMR Windows Utility - Driver Center'
                        UpdateTitle=[string]$target.Title
                        UpdateId=[string]$TargetUpdateId
                        Revision=[int]$TargetRevision
                        DeviceId=[string]$TargetDeviceId
                        DownloadedAt=(Get-Date).ToString('o')
                        DownloadEngine='AMR Internal HTTPS Engine'
                        Installable=$true
                        InstallMethod='PnPUtil with INF and signed catalog validation'
                        InstallableInfFiles=@($localInstallableInfFiles)
                        CatalogFile=[string]$bestInfCandidate.CatalogRelativePath
                        CatalogSignerThumbprint=[string]$bestInfCandidate.CatalogSignerThumbprint
                        ExpandedFiles=@($expandedFiles)
                        Files=@($savedFiles)
                    }
                    $manifestPath = Join-Path $savedFolder 'AMR_DriverPackage_Manifest.json'
                    $manifest | ConvertTo-Json -Depth 7 | Set-Content -LiteralPath $manifestPath -Encoding UTF8 -ErrorAction Stop
                    $manifestCheck = Get-Content -LiteralPath $manifestPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                    if ([string]$manifestCheck.UpdateId -ne [string]$TargetUpdateId -or [int]$manifestCheck.Revision -ne [int]$TargetRevision -or [string]$manifestCheck.DeviceId -ine [string]$TargetDeviceId -or @($manifestCheck.Files).Count -ne @($savedFiles).Count -or @($manifestCheck.ExpandedFiles).Count -ne @($expandedFiles).Count -or @($manifestCheck.InstallableInfFiles).Count -lt 1) {
                        throw 'The saved local driver package manifest failed its identity or file-inventory verification.'
                    }
                    $savedCopy = $true
                    $localInstallReady = $true
                    $savedCopyMessage = ('AMR downloaded, SHA-256 checked and prepared {0} content file(s); {1} signed INF package(s) match the selected device.' -f $savedFiles.Count,$localInstallableInfFiles.Count)
                    $completePayload = [pscustomobject]@{ Percent=100; BytesDownloaded=$aggregateBytes; BytesTotal=$aggregateTotal; SpeedBytesPerSecond=0; Stage='DirectDownloadCompleted'; Updated=(Get-Date).ToString('o') }
                    $completePayload | ConvertTo-Json -Compress | Set-Content -LiteralPath ($ProgressFile + '.tmp') -Encoding UTF8
                    Move-Item -LiteralPath ($ProgressFile + '.tmp') -Destination $ProgressFile -Force
                } catch {
                    $directFailure = [string]$_.Exception.Message
                    try { $directFailureDetails = [string]$_.Exception.ToString() } catch {}
                    try { $directFailureHResult = [int]$_.Exception.HResult } catch {}
                    try { $directFailureLine = [int]$_.InvocationInfo.ScriptLineNumber } catch {}
                    try { $directFailureStack = [string]$_.ScriptStackTrace } catch {}
                    $savedCopyMessage = 'AMR internal engine could not prepare a safe local driver package: ' + $directFailure
                    $savedCopy = $false
                    $localInstallReady = $false
                    $localInstallableInfFiles = @()
                    try {
                        $fallbackProgress = [pscustomobject]@{ Percent=3; BytesDownloaded=0; BytesTotal=0; SpeedBytesPerSecond=0; Stage='DirectPreparationFallback'; Error=$directFailure; Updated=(Get-Date).ToString('o') }
