                    }
                    $savedFolder = $null
                    $savedFiles = @()
                    try {
                        if ($null -eq $session) { throw 'Windows Update session is unavailable in the driver worker.' }
                        if ($null -eq $target) { throw 'The selected Windows Update driver object is unavailable; run Scan Device again.' }
                        if ($null -eq $collection -or [int]$collection.Count -lt 1) { throw 'The Windows Update collection is empty; the selected update cannot be downloaded.' }

                        # A previously cached update does not need a second Windows Update download call.
                        # This also avoids creating unnecessary COM download objects for cached updates.
                        if ([bool]$target.IsDownloaded) {
                            $wuaCacheReady = $true
                            $itemResult = $null
                        } else {
                            $downloader = $session.CreateUpdateDownloader()
                            if ($null -eq $downloader) { throw 'Windows Update did not create a download service object.' }
                            $downloader.Updates = $collection
                            $initialBytesTotal = [int64]0
                            try { $initialBytesTotal = [int64]$target.MaxDownloadSize } catch {}
                            $initialProgress = [pscustomobject]@{ Percent=2; BytesDownloaded=0; BytesTotal=$initialBytesTotal; SpeedBytesPerSecond=0; Stage='WuaFallbackDownloadStarting'; Updated=(Get-Date).ToString('o') }
                            $initialProgress | ConvertTo-Json -Compress | Set-Content -LiteralPath $ProgressFile -Encoding UTF8
                            # Windows PowerShell 5.1 COM interop can return fragile async job
                            # proxies when callbacks are omitted. Use the documented synchronous
                            # WUA Download() API instead; the worker runs off the UI thread.
                            # This avoids BeginDownload/EndDownload callback/proxy null paths in this worker.
                            $downloadStartPayload = [pscustomobject]@{ Percent=5; BytesDownloaded=0; BytesTotal=$initialBytesTotal; SpeedBytesPerSecond=0; Stage='WuaFallbackDownloadStarting'; Updated=(Get-Date).ToString('o') }
                            $downloadStartPayload | ConvertTo-Json -Compress | Set-Content -LiteralPath ($ProgressFile + '.tmp') -Encoding UTF8
                            Move-Item -LiteralPath ($ProgressFile + '.tmp') -Destination $ProgressFile -Force
                            $downloadStarted = Get-Date
                            $downloadResult = $downloader.Download()
                            if ($null -eq $downloadResult) { throw 'Windows Update Download() returned no download result object.' }
                            if (((Get-Date) - $downloadStarted).TotalMinutes -gt 180) { throw 'Windows Update fallback exceeded the 180-minute safety timeout.' }
                            $itemResult = $downloadResult.GetUpdateResult(0)
                            if ($null -eq $itemResult) { throw 'Windows Update returned no per-update download result for the selected driver.' }
                            $downloadCompletePayload = [pscustomobject]@{ Percent=95; BytesDownloaded=0; BytesTotal=$initialBytesTotal; SpeedBytesPerSecond=0; Stage='WuaFallbackDownloadCompleted'; Updated=(Get-Date).ToString('o') }
                            $downloadCompletePayload | ConvertTo-Json -Compress | Set-Content -LiteralPath ($ProgressFile + '.tmp') -Encoding UTF8
                            Move-Item -LiteralPath ($ProgressFile + '.tmp') -Destination $ProgressFile -Force
                            $wuaResultCode = [int]$itemResult.ResultCode
