                                    $verifyCandidate = $verifyResult.Updates.Item($verifyIndex)
                                    if ($null -ne $verifyCandidate -and [string]$verifyCandidate.Identity.UpdateID -eq [string]$TargetUpdateId -and [int]$verifyCandidate.Identity.RevisionNumber -eq [int]$TargetRevision) {
                                        $verifiedTarget = $verifyCandidate
                                        break
                                    }
                                    if ($null -ne $verifyCandidate) {
                                        try { if ([Runtime.InteropServices.Marshal]::IsComObject($verifyCandidate)) { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($verifyCandidate) } } catch {}
