                        try { $wuaDownloadErrorDetails = [string]$wuaErrorRecord.Exception.ToString() } catch {}
                        try { $wuaDownloadHResult = [int]$wuaErrorRecord.Exception.HResult } catch {}
                        try { $wuaDownloadErrorLine = [int]$wuaErrorRecord.InvocationInfo.ScriptLineNumber } catch {}
                        try { $wuaDownloadStack = [string]$wuaErrorRecord.ScriptStackTrace } catch {}
                    }
                }
