                    throw ('AMR internal engine failed: {0} [line {1}; HRESULT 0x{2:X8}] {3} Windows Update fallback failed: {4} [line {5}; HRESULT 0x{6:X8}] {7}' -f $savedCopyMessage,$directFailureLine,$directFailureHResult,$directFailureStack,$wuaDownloadError,$wuaDownloadErrorLine,$wuaDownloadHResult,$wuaDownloadStack)
                }
                if ($localInstallReady) {
                    $finalMessage = $savedCopyMessage + '. Windows Update was not used, so the package was downloaded only once. It is ready for local installation.'
                } else {
                    $finalMessage = $savedCopyMessage + '. AMR could not safely prepare this package, so Windows Update fallback completed the download and prepared its trusted installation cache.'
                }
                [pscustomobject]@{ Success=$true; OutcomeStatus='Success'; WuaReady=[bool]$wuaCacheReady; InstallReady=([bool]($localInstallReady -or $wuaCacheReady)); LocalInstallReady=[bool]$localInstallReady; Action='Download'; Message=$finalMessage; RebootRequired=$false; ResultCode=$(if ($wuaCacheReady) { [int]$wuaResultCode } else { 2 }); SavedCopy=$localInstallReady; SavedFolder=$savedFolder; SavedFiles=@($savedFiles); SavedCopyMessage=$savedCopyMessage; WuaDownloadError=$wuaDownloadError; WuaDownloadErrorDetails=$wuaDownloadErrorDetails; WuaDownloadHResult=$wuaDownloadHResult; WuaDownloadErrorLine=$wuaDownloadErrorLine; WuaDownloadStackTrace=$wuaDownloadStack; DirectFailure=$directFailure; DirectFailureDetails=$directFailureDetails; DirectFailureHResult=$directFailureHResult; DirectFailureLine=$directFailureLine; DirectFailureStackTrace=$directFailureStack }
            } else {
                $workerStage = 'LocalPackageManifestVerification'
                # Prefer AMR's verified local package. Windows Update installation is retained
                # only for updates whose package format required the fallback download path.
                $localManifestPath = Join-Path $TargetLocalPackageFolder 'AMR_DriverPackage_Manifest.json'
                $useLocalPackage = $false
                if (Test-Path -LiteralPath $localManifestPath -PathType Leaf) {
                    try {
                        $localManifest = Get-Content -LiteralPath $localManifestPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                        $manifestDeviceId = if (-not [string]::IsNullOrWhiteSpace([string]$localManifest.DeviceId)) { [string]$localManifest.DeviceId } else { [string]$localManifest.DeviceInstanceId }
                        if ([bool]$localManifest.Installable -and [string]$localManifest.UpdateId -eq [string]$TargetUpdateId -and [int]$localManifest.Revision -eq [int]$TargetRevision -and $manifestDeviceId -ieq [string]$TargetDeviceId -and @($localManifest.InstallableInfFiles).Count -gt 0) { $useLocalPackage = $true }
                        if($useLocalPackage) {
                            if([string]$TargetSourceAdapter -eq 'MicrosoftUpdateCatalog' -and ([string]$localManifest.SourceAdapter -ne 'MicrosoftUpdateCatalog' -or -not [bool]$localManifest.StagedByWindows)){throw 'Catalog manifest is not marked as Windows-staged.'}
                            if(@($localManifest.ExpandedFiles).Count -lt 1){throw 'The local package manifest has no extracted-file integrity inventory. Download and prepare the package again.'}
