                $installProgressStart | ConvertTo-Json -Compress | Set-Content -LiteralPath ($ProgressFile + '.tmp') -Encoding UTF8
                Move-Item -LiteralPath ($ProgressFile + '.tmp') -Destination $ProgressFile -Force
