$script:AppsView = [System.Windows.Data.CollectionViewSource]::GetDefaultView($script:SoftwareCatalog)

# Build category navigation entries with live catalog counts.
# Counts switch to installed-only totals whenever Show Installed is active.
$script:SelectedSoftwareCategory = 'All Applications'
$script:ShowInstalledOnly = $false
$script:SoftwareCategoryNames = @(
    $script:SoftwareCatalog |
        ForEach-Object { [string]$_.Category } |
        Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
        Sort-Object -Unique
)
$script:SoftwareCategories = @(
    [pscustomobject]@{ Name = 'All Applications'; DisplayText = 'All Applications'; CategoryNumber = '' }
) + @(
    for ($categoryIndex = 0; $categoryIndex -lt $script:SoftwareCategoryNames.Count; $categoryIndex++) {
        $categoryName = [string]$script:SoftwareCategoryNames[$categoryIndex]
        [pscustomobject]@{ Name = $categoryName; DisplayText = $categoryName; CategoryNumber = ('{0}' -f ($categoryIndex + 1)) }
    }
)
# Compact category navigation: keep category tiles plain and small.
$categoryTextFactory = New-Object System.Windows.FrameworkElementFactory([System.Windows.Controls.TextBlock])
$categoryTextFactory.SetBinding([System.Windows.Controls.TextBlock]::TextProperty, [System.Windows.Data.Binding]::new('DisplayText'))
$categoryTextFactory.SetValue([System.Windows.Controls.TextBlock]::TextWrappingProperty, [System.Windows.TextWrapping]::NoWrap)
$categoryTextFactory.SetValue([System.Windows.Controls.TextBlock]::TextTrimmingProperty, [System.Windows.TextTrimming]::CharacterEllipsis)
$categoryTextFactory.SetValue([System.Windows.Controls.TextBlock]::FontSizeProperty, [double]12.0)
$categoryTextFactory.SetValue([System.Windows.Controls.TextBlock]::MaxWidthProperty, 160.0)
$categoryTextFactory.SetValue([System.Windows.Controls.TextBlock]::VerticalAlignmentProperty, [System.Windows.VerticalAlignment]::Center)
$categoryTemplate = [System.Windows.DataTemplate]::new()
$categoryTemplate.VisualTree = $categoryTextFactory
(C 'SoftwareCategoryList').ItemTemplate = $categoryTemplate
(C 'SoftwareCategoryList').ItemsSource = $script:SoftwareCategories
(C 'SoftwareCategoryList').SelectedIndex = 0

function Update-AMRSoftwareCategoryCounts {
    $counts = @{}
    foreach ($entry in $script:SoftwareCategories) { $counts[[string]$entry.Name] = 0 }
    if ($script:ShowInstalledOnly) {
        foreach ($item in $script:InstalledAppsInventory) {
            $category = [string]$item.Category
            if ($category -and $counts.ContainsKey($category)) { $counts[$category] = [int]$counts[$category] + 1 }
        }
        $allCount = $script:InstalledAppsInventory.Count
    } else {
        foreach ($item in $script:SoftwareCatalog) {
            $category = [string]$item.Category
            if ($category -and $counts.ContainsKey($category)) { $counts[$category] = [int]$counts[$category] + 1 }
        }
        $allCount = $script:SoftwareCatalog.Count
    }
    foreach ($entry in $script:SoftwareCategories) {
        $count = if ($entry.Name -eq 'All Applications') { $allCount } else { [int]$counts[[string]$entry.Name] }
        $entry.DisplayText = '{0} ({1})' -f $entry.Name, $count
    }
    try { (C 'SoftwareCategoryList').Items.Refresh() } catch {}
}

Update-AMRSoftwareCategoryCounts
try { (C 'UninstallSelectedBtn').Visibility = 'Collapsed' } catch {}

# Universal installed-app inventory is deliberately separate from SoftwareCatalog.
# Unknown apps must never enter Smart Install / Update / Repair pipelines.
$script:InstalledAppsInventory = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
$script:InstalledAppsView = $null

function New-AMRInstalledInventoryRecord {
    param(
        [string]$Name, [string]$Publisher='', [string]$DisplayVersion='', [string]$InstallDate='',
        [string]$InstallLocation='', [string]$DisplayIcon='', [string]$ShortcutPath='', [string]$UninstallString='', [string]$QuietUninstallString='',
        [bool]$WindowsInstaller=$false, [string]$RegistryKeyPath='', [string]$RegistryHive='',
        [string]$RegistryView='', [string]$AppxPackageFullName='', [string]$PackageFamilyName='',
        [string]$WingetId='', [string]$ChocoId='', [string]$ScoopName='', [string]$Source='',
        [bool]$IsCatalogApp=$false, [string]$CatalogId='', [bool]$IsInstalled=$true,
        [bool]$CanUninstall=$false, [string]$UninstallMethod='', [string]$UninstallReason='',
        [string]$PortableExecutablePath='', [string]$PortableRootFolder='', [bool]$IsPortable=$false,
        [string]$IdentityKey='', [string]$Confidence='High'
    )
    if ([string]::IsNullOrWhiteSpace($IdentityKey)) {
        $IdentityKey = if ($RegistryKeyPath) { 'REG:' + $RegistryKeyPath.ToLowerInvariant() }
            elseif ($AppxPackageFullName) { 'APPX:' + $AppxPackageFullName.ToLowerInvariant() }
            elseif ($WingetId) { 'WINGET:' + $WingetId.ToLowerInvariant() }
            elseif ($ChocoId) { 'CHOCO:' + $ChocoId.ToLowerInvariant() }
            elseif ($ScoopName) { 'SCOOP:' + $ScoopName.ToLowerInvariant() }
            elseif ($PortableExecutablePath) { 'PORTABLE:' + $PortableExecutablePath.ToLowerInvariant() }
            else { 'OTHER:' + (($Name -replace '\s+',' ').Trim().ToLowerInvariant()) }
    }
    $initials = (($Name -split '\s+' | Where-Object { $_ } | Select-Object -First 2 | ForEach-Object { $_.Substring(0,1) }) -join '').ToUpperInvariant()
    return [pscustomobject][ordered]@{
        Name=$Name; Publisher=$Publisher; DisplayVersion=$DisplayVersion; InstallDate=$InstallDate
        Category=''; IsUniversalInventory=$false; DetailsExpanded=$false; DisplayInstallPath=''; HasCopyableInstallPath=$false; InstallLocation=$InstallLocation; DisplayIcon=$DisplayIcon; ShortcutPath=$ShortcutPath; UninstallString=$UninstallString; QuietUninstallString=$QuietUninstallString
        WindowsInstaller=$WindowsInstaller; RegistryKeyPath=$RegistryKeyPath; RegistryHive=$RegistryHive; RegistryView=$RegistryView
        AppxPackageFullName=$AppxPackageFullName; PackageFamilyName=$PackageFamilyName; WingetId=$WingetId
        ChocoId=$ChocoId; ScoopName=$ScoopName; Source=$Source; IsCatalogApp=$IsCatalogApp; CatalogId=$CatalogId
        IsInstalled=$IsInstalled; IsSelected=$false; CanUninstall=$CanUninstall; UninstallMethod=$UninstallMethod
        UninstallReason=$UninstallReason; Initials=$initials; Icon=$null; Id=$(if($CatalogId){$CatalogId}elseif($WingetId){$WingetId}elseif($AppxPackageFullName){$AppxPackageFullName}else{$IdentityKey})
        IdentityKey=$IdentityKey; Confidence=$Confidence; PortableExecutablePath=$PortableExecutablePath
        PortableRootFolder=$PortableRootFolder; IsPortable=$IsPortable
    }
}

function Get-AMRUniversalInstalledInventory {
    [CmdletBinding()]
    param(
        [string]$WingetRawOutput = '',
        [switch]$SkipWingetScan
    )
    $records = New-Object 'System.Collections.Generic.List[object]'
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $readProperty = { param($object, [string]$propertyName) $property = $object.PSObject.Properties[$propertyName]; if ($property) { return $property.Value }; return $null }
    $registrySpecs = @(
        @{ Path='HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*'; Hive='HKLM'; View='64-bit' },
        @{ Path='HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'; Hive='HKLM'; View='32-bit' },
        @{ Path='HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*'; Hive='HKCU'; View='User' },
        @{ Path='HKCU:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'; Hive='HKCU'; View='User-32-bit' }
    )
    foreach ($spec in $registrySpecs) {
        try {
            foreach ($entry in @(Get-ItemProperty -Path $spec.Path -ErrorAction SilentlyContinue)) {
                $name = [string](& $readProperty $entry 'DisplayName')
                if ([string]::IsNullOrWhiteSpace($name)) { continue }
                $systemComponent = & $readProperty $entry 'SystemComponent'
                $releaseType = [string](& $readProperty $entry 'ReleaseType')
                $parentKeyName = [string](& $readProperty $entry 'ParentKeyName')
                $noDisplay = & $readProperty $entry 'NoDisplay'
                $protectedComponent = ($systemComponent -eq 1) -or (-not [string]::IsNullOrWhiteSpace($releaseType)) -or (-not [string]::IsNullOrWhiteSpace($parentKeyName)) -or ($noDisplay -eq 1)
                $keyPath = [string](& $readProperty $entry 'PSPath')
                if ([string]::IsNullOrWhiteSpace($keyPath)) { continue }
                $uninstall = [string](& $readProperty $entry 'UninstallString')
                $quiet = [string](& $readProperty $entry 'QuietUninstallString')
                $msiValue = & $readProperty $entry 'WindowsInstaller'
                $msi = $false; try { $msi = ([int]$msiValue -eq 1) } catch {}
                $hasCommand = $msi -or -not [string]::IsNullOrWhiteSpace($uninstall) -or -not [string]::IsNullOrWhiteSpace($quiet)
                $can = $hasCommand -and -not $protectedComponent
                $method = if ($msi) {'MSI'} elseif ($hasCommand) {'Registry'} else {''}
                $reason = if ($protectedComponent) {'Windows marks this as a system/hidden/parent component; automatic removal is blocked to protect shared dependencies.'} elseif ($can) {'Registered native uninstaller is available.'} else {'Windows has no registered uninstall command for this entry.'}
                $record = New-AMRInstalledInventoryRecord -Name $name -Publisher ([string](& $readProperty $entry 'Publisher')) -DisplayVersion ([string](& $readProperty $entry 'DisplayVersion')) -InstallDate ([string](& $readProperty $entry 'InstallDate')) -InstallLocation ([string](& $readProperty $entry 'InstallLocation')) -DisplayIcon ([string](& $readProperty $entry 'DisplayIcon')) -UninstallString $uninstall -QuietUninstallString $quiet -WindowsInstaller $msi -RegistryKeyPath $keyPath -RegistryHive $spec.Hive -RegistryView $spec.View -Source 'Windows Registry' -CanUninstall $can -UninstallMethod $method -UninstallReason $reason -IdentityKey ('REG:' + $keyPath.ToLowerInvariant())
                if ($seen.Add($record.IdentityKey)) { [void]$records.Add($record) }
            }
        } catch {}
    }

    # AppX/MSIX: current-user packages only. AllUsers staged registrations are not
    # represented as installed apps and must not be removed on behalf of other users.
    try {
        foreach ($pkg in @(Get-AppxPackage -ErrorAction SilentlyContinue)) {
            if ([string]::IsNullOrWhiteSpace([string]$pkg.PackageFullName)) { continue }
            $appxFramework = & $readProperty $pkg 'IsFramework'
            $appxResource = & $readProperty $pkg 'IsResourcePackage'
            $appxBundle = & $readProperty $pkg 'IsBundle'
            $appxProtected = [bool]$appxFramework -or [bool]$appxResource -or [bool]$appxBundle
            $appxCanRemove = -not $appxProtected
            $appxReason = if ($appxProtected) {'Framework/resource/bundle package is protected as a shared dependency.'} else {'Exact current-user AppX/MSIX package identity is available.'}
            $record = New-AMRInstalledInventoryRecord -Name ([string](& $readProperty $pkg 'Name')) -Publisher ([string](& $readProperty $pkg 'Publisher')) -DisplayVersion ([string](& $readProperty $pkg 'Version')) -AppxPackageFullName ([string](& $readProperty $pkg 'PackageFullName')) -PackageFamilyName ([string](& $readProperty $pkg 'PackageFamilyName')) -Source 'AppX/MSIX' -CanUninstall $appxCanRemove -UninstallMethod 'AppX' -UninstallReason $appxReason -IdentityKey ('APPX:' + ([string]$pkg.PackageFullName).ToLowerInvariant())
            if ($seen.Add($record.IdentityKey)) { [void]$records.Add($record) }
        }
    } catch {}

    # WinGet, Chocolatey and Scoop are supplemental identity sources. Their records
    # are retained only when not already represented by a native uninstall identity.
    try {
        $lines = @()
        if ($SkipWingetScan) {
            if (-not [string]::IsNullOrWhiteSpace($WingetRawOutput)) {
                $lines = @($WingetRawOutput -split "`r?`n")
            }
        } else {
            $wg = Get-Command winget.exe -ErrorAction SilentlyContinue
            if ($wg) {
                $out = & $wg.Source list --disable-interactivity --accept-source-agreements 2>$null
                $lines = @($out | ForEach-Object { [string]$_ })
            }
        }
        if ($lines.Count -gt 0) {
            $header = -1; $idStart = -1; $verStart = -1
            for ($i=0; $i -lt $lines.Count; $i++) {
                $mi=[regex]::Match($lines[$i],'(?i)\bId\b'); $mv=[regex]::Match($lines[$i],'(?i)\bVersion\b')
                if ($mi.Success -and $mv.Success -and $mv.Index -gt $mi.Index) { $header=$i; $idStart=$mi.Index; $verStart=$mv.Index; break }
            }
            if ($header -ge 0) {
                for ($i=$header+1; $i -lt $lines.Count; $i++) {
                    $line=$lines[$i]; if ($line.Length -le $idStart) { continue }
                    $len=[Math]::Min(($verStart-$idStart),($line.Length-$idStart)); if ($len -le 0) { continue }
                    $id=$line.Substring($idStart,$len).Trim()
                    $wingetDisplayName = $line.Substring(0,$idStart).Trim()
                    if ([string]::IsNullOrWhiteSpace($wingetDisplayName)) { $wingetDisplayName = $id }
                    if ($id -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]*$') { continue }
                    $norm=($id -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
                    $already=$false
                    foreach($r in $records){ if((([string]$r.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()) -eq $norm){$already=$true;break} }
                    if(-not $already){ $rec=New-AMRInstalledInventoryRecord -Name $wingetDisplayName -WingetId $id -Source 'WinGet' -CanUninstall $true -UninstallMethod 'WinGet' -UninstallReason 'Exact WinGet package ID was reported by winget list.' -IdentityKey ('WINGET:'+$id.ToLowerInvariant()) -Confidence 'Medium'; if($seen.Add($rec.IdentityKey)){[void]$records.Add($rec)} }
                }
            }
        }
    } catch {}
    $chocoRoots=@(); if($env:ChocolateyInstall){$chocoRoots+= $env:ChocolateyInstall}; if($env:ProgramData){$chocoRoots+= (Join-Path $env:ProgramData 'chocolatey')}
    foreach($root in @($chocoRoots | Select-Object -Unique)){
        $lib=Join-Path $root 'lib'; if(-not(Test-Path -LiteralPath $lib -PathType Container)){continue}
        foreach($folder in @(Get-ChildItem -LiteralPath $lib -Directory -ErrorAction SilentlyContinue)){
            if(@(Get-ChildItem -LiteralPath $folder.FullName -Filter '*.nuspec' -File -ErrorAction SilentlyContinue).Count -gt 0){
                $id=$folder.Name; $norm=($id -replace '[^a-zA-Z0-9]','').ToLowerInvariant(); $exists=$false
                foreach($r in $records){if((([string]$r.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()) -eq $norm){$exists=$true;break}}
                if(-not $exists){$rec=New-AMRInstalledInventoryRecord -Name $id -ChocoId $id -Source 'Chocolatey' -CanUninstall $true -UninstallMethod 'Chocolatey' -UninstallReason 'Exact local Chocolatey package folder and nuspec were found.' -IdentityKey ('CHOCO:'+$id.ToLowerInvariant()) -Confidence 'Medium'; if($seen.Add($rec.IdentityKey)){[void]$records.Add($rec)}}
            }
        }
    }
    $scoopRoots=@(); if($env:SCOOP){$scoopRoots+=$env:SCOOP}; if($env:SCOOP_GLOBAL){$scoopRoots+=$env:SCOOP_GLOBAL}; if($env:USERPROFILE){$scoopRoots+=(Join-Path $env:USERPROFILE 'scoop')}; if($env:ProgramData){$scoopRoots+=(Join-Path $env:ProgramData 'scoop')}
    foreach($root in @($scoopRoots | Select-Object -Unique)){
        $apps=Join-Path $root 'apps'; if(-not(Test-Path -LiteralPath $apps -PathType Container)){continue}
        foreach($folder in @(Get-ChildItem -LiteralPath $apps -Directory -ErrorAction SilentlyContinue)){
            $id=$folder.Name -replace '\\current$',''; $norm=($id -replace '[^a-zA-Z0-9]','').ToLowerInvariant(); $exists=$false
            foreach($r in $records){if((([string]$r.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()) -eq $norm){$exists=$true;break}}
            if(-not $exists){$rec=New-AMRInstalledInventoryRecord -Name $id -ScoopName $id -InstallLocation $folder.FullName -Source 'Scoop' -CanUninstall $true -UninstallMethod 'Scoop' -UninstallReason 'Exact Scoop app directory was found.' -IdentityKey ('SCOOP:'+$id.ToLowerInvariant()) -Confidence 'Medium'; if($seen.Add($rec.IdentityKey)){[void]$records.Add($rec)}}
        }
    }

    # Conservative portable discovery: only shortcuts in Desktop/Start Menu and
    # executables directly inside known portable roots / top-level Downloads folders.
    $shortcutRoots=@(); foreach($v in @([Environment]::GetFolderPath('Desktop'),(Join-Path $env:APPDATA 'Microsoft\Windows\Start Menu\Programs'),(Join-Path $env:ProgramData 'Microsoft\Windows\Start Menu\Programs'))){if($v -and (Test-Path -LiteralPath $v -PathType Container)){$shortcutRoots+=$v}}
    $portableRoots=@(); if($env:USERPROFILE){$portableRoots+=(Join-Path $env:USERPROFILE 'PortableApps')}; if($env:ProgramData){$portableRoots+=(Join-Path $env:ProgramData 'PortableApps')}; $portableRoots+='C:\PortableApps'
    $targets=New-Object 'System.Collections.Generic.List[string]'
    try {
        $ws=New-Object -ComObject WScript.Shell
        foreach($root in $shortcutRoots){ foreach($lnk in @(Get-ChildItem -LiteralPath $root -Filter '*.lnk' -File -Recurse -ErrorAction SilentlyContinue)){ try{$sc=$ws.CreateShortcut($lnk.FullName);$target=[string]$sc.TargetPath;if($target -and [IO.Path]::GetExtension($target) -ieq '.exe' -and (Test-Path -LiteralPath $target -PathType Leaf)){[void]$targets.Add($target)}}catch{} } }
    } catch {}
    foreach($root in @($portableRoots | Select-Object -Unique)){
        if(Test-Path -LiteralPath $root -PathType Container){foreach($exe in @(Get-ChildItem -LiteralPath $root -Filter '*.exe' -File -Recurse -ErrorAction SilentlyContinue)){[void]$targets.Add($exe.FullName)}}
    }
    $downloads=Join-Path $env:USERPROFILE 'Downloads'
    if(Test-Path -LiteralPath $downloads -PathType Container){foreach($exe in @(Get-ChildItem -LiteralPath $downloads -Filter '*.exe' -File -ErrorAction SilentlyContinue)){[void]$targets.Add($exe.FullName)}}
    $blocked=@('setup.exe','uninstall.exe','unins000.exe','update.exe','crashpad_handler.exe','vc_redist.x64.exe','vc_redist.x86.exe')
    foreach($target in @($targets | Select-Object -Unique)){
        try {
            $leaf=[IO.Path]::GetFileName($target); if($blocked -contains $leaf.ToLowerInvariant()){continue}
            $root=[IO.Path]::GetDirectoryName($target); $base=[IO.Path]::GetFileNameWithoutExtension($target)
            if($root -match '(?i)\\(Windows|System32|SysWOW64|Program Files|Program Files \(x86\))($|\\)'){continue}
            $managedPortable = $false; $portableAppRoot = $root
            foreach($allowedRoot in @($portableRoots | Select-Object -Unique)){
                try {
                    $allowedFull=[IO.Path]::GetFullPath($allowedRoot).TrimEnd('\')+'\'
                    $targetFull=[IO.Path]::GetFullPath($target)
                    if($targetFull.StartsWith($allowedFull,[StringComparison]::OrdinalIgnoreCase)){
                        $relative=$targetFull.Substring($allowedFull.Length); $firstPart=($relative -split '[\\/]')[0]
                        if(-not [string]::IsNullOrWhiteSpace($firstPart)){$portableAppRoot=Join-Path $allowedRoot $firstPart;if(Test-Path -LiteralPath $portableAppRoot -PathType Container){$managedPortable=$true;break}else{$portableAppRoot=$root}}
                    }
                } catch {}
            }
            $existing=$false; foreach($r in $records){if($r.InstallLocation -and ([string]$r.InstallLocation).TrimEnd('\') -ieq $portableAppRoot.TrimEnd('\')){$existing=$true;break}}
            if($existing){continue}
            $portableReason = if($managedPortable){'Exact application folder is inside a designated PortableApps root; removal is limited to this folder.'}else{'Portable executable found via shortcut or Downloads. Its containing folder is not a managed PortableApps root, so deletion is disabled.'}
            $rec=New-AMRInstalledInventoryRecord -Name $base -InstallLocation $portableAppRoot -Source 'Portable candidate' -CanUninstall $managedPortable -UninstallMethod $(if($managedPortable){'Portable'}else{''}) -UninstallReason $portableReason -PortableExecutablePath $target -PortableRootFolder $portableAppRoot -IsPortable $true -IdentityKey ('PORTABLE:'+$portableAppRoot.ToLowerInvariant()) -Confidence 'Low'
            if($seen.Add($rec.IdentityKey)){[void]$records.Add($rec)}
        } catch {}
    }
    return @($records | Sort-Object Name)
}

function Set-AMRInstalledCatalogMatches {
    param(
        [object[]]$Catalog,
        [object]$InstalledIdentities,
        [object]$WingetIdentities,
        [object]$ChocoIdentities,
        [object]$ScoopIdentities,
        [string]$WingetRawOutput
    )

    # Canonical aliases for known catalog/installer naming differences.
    $identityAliases = @{
        'everythingsearch' = @('everything')
        'visualstudiocode' = @('vscode','microsoftvisualstudiocode')
        'microsoftedgewebview2runtime' = @('webview2runtime','microsoftedgewebview2')
        'googlechrome' = @('chrome')
        'microsoftedge' = @('edge')
        'discord' = @('discord')
        '7zip' = @('7zip')
        'vlcmediaplayer' = @('vlc')
        'sumatrapdf' = @('sumatrapdf')
        'sharex' = @('sharex')
    }

    $installedCount = 0
    foreach ($app in $Catalog) {
        $isInstalled = $false
        $candidateIdentities = New-Object 'System.Collections.Generic.List[string]'
        foreach ($identity in @([string]$app.Name, [string]$app.Id, [string]$app.ChocoId)) {
            if ([string]::IsNullOrWhiteSpace($identity)) { continue }
            $normalized = ($identity -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
            if ($normalized.Length -ge 3 -and -not $candidateIdentities.Contains($normalized)) { $candidateIdentities.Add($normalized) }
        }

        # The final segment of a package ID often matches its Windows display name
        # (for example, Vendor.ProductName vs. Product Name).
        if (-not [string]::IsNullOrWhiteSpace([string]$app.Id) -and [string]$app.Id -match '\.') {
            $idSuffix = ([string]$app.Id -split '\.')[-1]
            $normalizedSuffix = ($idSuffix -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
            if ($normalizedSuffix.Length -ge 3 -and -not $candidateIdentities.Contains($normalizedSuffix)) { $candidateIdentities.Add($normalizedSuffix) }
        }

        foreach ($baseIdentity in @($candidateIdentities.ToArray())) {
            if ($identityAliases.ContainsKey($baseIdentity)) {
                foreach ($alias in $identityAliases[$baseIdentity]) {
                    $normalizedAlias = ($alias -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                    if ($normalizedAlias.Length -ge 3 -and -not $candidateIdentities.Contains($normalizedAlias)) { $candidateIdentities.Add($normalizedAlias) }
                }
            }
        }

        # Strong package-manager evidence: exact WinGet package ID, Chocolatey ID,
        # or Scoop app-folder identity.
        $normalizedCatalogId = ([string]$app.Id -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
        $normalizedChocoId = ([string]$app.ChocoId -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
        if ($normalizedCatalogId.Length -ge 3 -and $wingetIdentities.Contains($normalizedCatalogId)) { $isInstalled = $true }
        if (-not $isInstalled -and $normalizedChocoId.Length -ge 3 -and $chocoIdentities.Contains($normalizedChocoId)) { $isInstalled = $true }
        if (-not $isInstalled) {
            foreach ($candidate in $candidateIdentities) {
                if ($scoopIdentities.Contains($candidate)) { $isInstalled = $true; break }
            }
        }

        # Windows registry and AppX identities, using exact normalized matches first.
        if (-not $isInstalled) {
            foreach ($normalized in $candidateIdentities) {
                if ($installedIdentities.Contains($normalized)) { $isInstalled = $true; break }
                # Accept only a version/architecture suffix after a complete known identity.
                foreach ($observed in $installedIdentities) {
                    if ($observed.Length -gt $normalized.Length -and $observed.StartsWith($normalized, [System.StringComparison]::OrdinalIgnoreCase)) {
                        $suffix = $observed.Substring($normalized.Length)
                        if ($suffix -match '^\d+(x64|x86|64bit|32bit)?$') { $isInstalled = $true; break }
                    }
                }
                if ($isInstalled) { break }
            }
        }

        # Fallback for WinGet CLI versions whose table headings/layout differ.
        if (-not $isInstalled -and -not [string]::IsNullOrWhiteSpace($wingetRawOutput) -and -not [string]::IsNullOrWhiteSpace([string]$app.Id)) {
            $escapedId = [regex]::Escape([string]$app.Id)
            if ($wingetRawOutput -match ('(?im)(?<![A-Za-z0-9_.-])' + $escapedId + '(?![A-Za-z0-9_.-])')) { $isInstalled = $true }
        }

        $app.IsInstalled = $isInstalled
        if ($isInstalled) { $installedCount++ }
    }

    return $installedCount
}

function Update-AMRInstalledCatalogState {
    # Build a multi-source local inventory once, then match it against the catalog.
    # Evidence sources: Windows uninstall registry, AppX/MSIX, WinGet, Chocolatey and Scoop.
    # Provisioned AppX packages are intentionally excluded: provisioned does not mean installed.
    $installedIdentities = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $wingetIdentities = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $chocoIdentities = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $scoopIdentities = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)

    # 1. Windows uninstall inventory: machine/user and 64-bit/32-bit registry locations.
    $registryEntryCount = 0
    $uninstallPaths = @(
        'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )
    foreach ($registryPath in $uninstallPaths) {
        try {
            foreach ($entry in @(Get-ItemProperty -Path $registryPath -ErrorAction SilentlyContinue)) {
                $displayNameProperty = $entry.PSObject.Properties['DisplayName']
                $childNameProperty = $entry.PSObject.Properties['PSChildName']
                $displayNameValue = if ($displayNameProperty -and $null -ne $displayNameProperty.Value) { [string]$displayNameProperty.Value } else { '' }
                $childNameValue = if ($childNameProperty -and $null -ne $childNameProperty.Value) { [string]$childNameProperty.Value } else { '' }
                if (-not [string]::IsNullOrWhiteSpace($displayNameValue)) { $registryEntryCount++ }
                foreach ($identity in @($displayNameValue, $childNameValue)) {
                    if (-not [string]::IsNullOrWhiteSpace($identity)) {
                        $normalized = ($identity -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                        if ($normalized.Length -ge 3) { [void]$installedIdentities.Add($normalized) }
                    }
                }
            }
        } catch {
            Write-AMRLog "Could not read installed software inventory from '$registryPath': $($_.Exception.Message)" WARNING Software
        }
    }

    # 2. AppX/MSIX packages installed for the current user or any user on this PC.
    $appxPackageCount = 0
    try {
        $appxPackages = @(Get-AppxPackage -AllUsers -ErrorAction Stop)
    } catch {
        Write-AMRLog "All-user AppX inventory was unavailable; falling back to the current user: $($_.Exception.Message)" WARNING Software
        try { $appxPackages = @(Get-AppxPackage -ErrorAction SilentlyContinue) } catch { $appxPackages = @() }
    }
    foreach ($package in $appxPackages) {
        # When Windows exposes per-user package states, count only packages registered
        # as Installed for at least one user; do not count packages merely Staged.
        $userInfoProperty = $package.PSObject.Properties['PackageUserInformation']
        if ($userInfoProperty -and $null -ne $userInfoProperty.Value) {
            $hasInstalledUser = $false
            foreach ($userInfo in @($userInfoProperty.Value)) {
                if ([string]$userInfo.InstallState -eq 'Installed') { $hasInstalledUser = $true; break }
            }
            if (-not $hasInstalledUser) { continue }
        }
        $appxPackageCount++
        foreach ($identity in @([string]$package.Name, [string]$package.PackageFamilyName, [string]$package.PackageFullName)) {
            if (-not [string]::IsNullOrWhiteSpace($identity)) {
                $normalized = ($identity -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                if ($normalized.Length -ge 3) { [void]$installedIdentities.Add($normalized) }
            }
        }
    }

    # 3. WinGet's own installed-package inventory. Parse only the ID column when possible;
    # the exact-ID fallback handles CLI table-layout differences without loose name matching.
    $wingetRawOutput = ''
    $wingetAvailable = $false
    try {
        $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
        if ($winget) {
            $wingetAvailable = $true
            $wingetToken = [guid]::NewGuid().ToString('N')
            $wingetStdoutPath = Join-Path $env:TEMP ("AMR_ShowInstalled_{0}.out" -f $wingetToken)
            $wingetStderrPath = Join-Path $env:TEMP ("AMR_ShowInstalled_{0}.err" -f $wingetToken)
            $wingetProcess = $null
            $wingetExitCode = -1
            try {
                $wingetProcess = Start-Process -FilePath $winget.Source -ArgumentList 'list --disable-interactivity --accept-source-agreements' -PassThru -WindowStyle Hidden -RedirectStandardOutput $wingetStdoutPath -RedirectStandardError $wingetStderrPath -ErrorAction Stop
                if (-not $wingetProcess.WaitForExit(10000)) {
                    try { Stop-Process -Id $wingetProcess.Id -Force -ErrorAction SilentlyContinue } catch {}
                    throw 'WinGet installed-package inventory timed out after 10 seconds.'
                }
                $wingetProcess.WaitForExit()
                $wingetExitCode = [int]$wingetProcess.ExitCode
                $wingetStdout = if (Test-Path -LiteralPath $wingetStdoutPath) { [string](Get-Content -LiteralPath $wingetStdoutPath -Raw -ErrorAction SilentlyContinue) } else { '' }
                $wingetStderr = if (Test-Path -LiteralPath $wingetStderrPath) { [string](Get-Content -LiteralPath $wingetStderrPath -Raw -ErrorAction SilentlyContinue) } else { '' }
                $wingetRawOutput = $wingetStdout
                $wingetOutput = @($wingetStdout -split "`r?`n")
            } finally {
                if ($wingetProcess) { try { $wingetProcess.Dispose() } catch {} }
                foreach ($tempOutput in @($wingetStdoutPath,$wingetStderrPath)) {
                    if (Test-Path -LiteralPath $tempOutput) { Remove-Item -LiteralPath $tempOutput -Force -ErrorAction SilentlyContinue }
                }
            }
            if ($wingetExitCode -eq 0) {
                $headerIndex = -1
                $idColumnStart = -1
                $versionColumnStart = -1
                for ($lineIndex = 0; $lineIndex -lt $wingetOutput.Count; $lineIndex++) {
                    $lineText = [string]$wingetOutput[$lineIndex]
                    $idHeader = [regex]::Match($lineText, '(?i)\bId\b')
                    $versionHeader = [regex]::Match($lineText, '(?i)\bVersion\b')
                    if ($idHeader.Success -and $versionHeader.Success -and $versionHeader.Index -gt $idHeader.Index) {
                        $headerIndex = $lineIndex
                        $idColumnStart = $idHeader.Index
                        $versionColumnStart = $versionHeader.Index
                        break
                    }
                }
                if ($headerIndex -ge 0) {
                    for ($lineIndex = ($headerIndex + 1); $lineIndex -lt $wingetOutput.Count; $lineIndex++) {
                        $lineText = [string]$wingetOutput[$lineIndex]
                        if ($lineText.Length -le $idColumnStart) { continue }
                        $fieldLength = [Math]::Min(($versionColumnStart - $idColumnStart), ($lineText.Length - $idColumnStart))
                        if ($fieldLength -le 0) { continue }
                        $packageId = $lineText.Substring($idColumnStart, $fieldLength).Trim()
                        if ($packageId -match '^[A-Za-z0-9][A-Za-z0-9._-]*$') {
                            $normalizedId = ($packageId -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                            if ($normalizedId.Length -ge 3) { [void]$wingetIdentities.Add($normalizedId) }
                        }
                    }
                }
            } else {
                Write-AMRLog ("WinGet installed-package inventory returned exit code {0}; registry/AppX detection will still be used. {1}" -f $wingetExitCode,$wingetStderr) WARNING Software
            }
        }
    } catch {
        Write-AMRLog "Could not read WinGet installed-package inventory: $($_.Exception.Message)" WARNING Software
    }

    # 4. Chocolatey local package folders are authoritative for Chocolatey-managed installs.
    $chocoRoots = @()
    if (-not [string]::IsNullOrWhiteSpace($env:ChocolateyInstall)) { $chocoRoots += $env:ChocolateyInstall }
    $chocoRoots += (Join-Path $env:ProgramData 'chocolatey')
    foreach ($chocoRoot in @($chocoRoots | Select-Object -Unique)) {
        $chocoLib = Join-Path $chocoRoot 'lib'
        if (-not (Test-Path -LiteralPath $chocoLib -PathType Container)) { continue }
        try {
            foreach ($packageFolder in @(Get-ChildItem -LiteralPath $chocoLib -Directory -ErrorAction SilentlyContinue)) {
                $nuspecFiles = @(Get-ChildItem -LiteralPath $packageFolder.FullName -Filter '*.nuspec' -File -ErrorAction SilentlyContinue)
                if ($nuspecFiles.Count -gt 0) {
                    $normalizedFolder = ($packageFolder.Name -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                    if ($normalizedFolder.Length -ge 3) { [void]$chocoIdentities.Add($normalizedFolder) }
                }
            }
        } catch {
            Write-AMRLog "Could not read Chocolatey package inventory at '$chocoLib': $($_.Exception.Message)" WARNING Software
        }
    }

    # 5. Scoop app folders (user and global installations).
    $scoopRoots = @()
    if (-not [string]::IsNullOrWhiteSpace($env:SCOOP)) { $scoopRoots += $env:SCOOP }
    if (-not [string]::IsNullOrWhiteSpace($env:SCOOP_GLOBAL)) { $scoopRoots += $env:SCOOP_GLOBAL }
    if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) { $scoopRoots += (Join-Path $env:USERPROFILE 'scoop') }
    if (-not [string]::IsNullOrWhiteSpace($env:ProgramData)) { $scoopRoots += (Join-Path $env:ProgramData 'scoop') }
    foreach ($scoopRoot in @($scoopRoots | Select-Object -Unique)) {
        $appsPath = Join-Path $scoopRoot 'apps'
        if (-not (Test-Path -LiteralPath $appsPath -PathType Container)) { continue }
        try {
            foreach ($appFolder in @(Get-ChildItem -LiteralPath $appsPath -Directory -ErrorAction SilentlyContinue)) {
                $normalizedFolder = ($appFolder.Name -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                if ($normalizedFolder.Length -ge 3) { [void]$scoopIdentities.Add($normalizedFolder) }
            }
        } catch {
            Write-AMRLog "Could not read Scoop package inventory at '$appsPath': $($_.Exception.Message)" WARNING Software
        }
    }

    $installedCount = Set-AMRInstalledCatalogMatches `
        -Catalog $script:SoftwareCatalog `
        -InstalledIdentities $installedIdentities `
        -WingetIdentities $wingetIdentities `
        -ChocoIdentities $chocoIdentities `
        -ScoopIdentities $scoopIdentities `
        -WingetRawOutput $wingetRawOutput

    Write-AMRLog ("Installed inventory scanned: {0} registry entries, {1} AppX/MSIX packages, {2} WinGet IDs, {3} Chocolatey packages, {4} Scoop apps. Catalog matches: {5}." -f $registryEntryCount,$appxPackageCount,$wingetIdentities.Count,$chocoIdentities.Count,$scoopIdentities.Count,$installedCount) INFO Software
    return [pscustomobject]@{
        Count = [int]$installedCount
        WingetRawOutput = [string]$wingetRawOutput
    }
}


# ----------------------------------------------------------
# Background installed-inventory scanner
# The inventory scan runs in a dedicated runspace. Only the
# final IsInstalled flags are copied back on the WPF UI thread.
# ----------------------------------------------------------
$script:InstalledScanState = @{
    Current = $null
    Inventory = @()
    Ready = $false
    Count = 0
    Error = ''
    PendingShow = $false
    RescanRequested = $false
    CacheLoaded = $false
}

# Persistent snapshot: the last completed inventory is loaded immediately on the
# next launch, while a fresh scan refreshes it in the background.
$script:InstalledInventoryCacheDir = Join-Path $script:AppRoot 'Cache'
$script:InstalledInventoryCacheFile = Join-Path $script:InstalledInventoryCacheDir 'InstalledInventoryCache.json'
try { New-Item -ItemType Directory -Force -Path $script:InstalledInventoryCacheDir | Out-Null } catch {}

function Get-AMRInstalledCatalogFingerprint {
    try {
        $catalogIds = @($script:SoftwareCatalog | ForEach-Object { [string]$_.Id }) -join "`n"
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($catalogIds)
        $sha = [System.Security.Cryptography.SHA256]::Create()
        try { return ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant() }
        finally { $sha.Dispose() }
    } catch { return '' }
}

function Import-AMRInstalledInventoryCache {
    param([switch]$Quiet)
    $cachePath = [string]$script:InstalledInventoryCacheFile
    if (-not (Test-Path -LiteralPath $cachePath -PathType Leaf)) { return $false }
    try {
        $cache = Get-Content -LiteralPath $cachePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        if ([int]$cache.SchemaVersion -ne 1) { return $false }
        $fingerprint = Get-AMRInstalledCatalogFingerprint
        if ([string]::IsNullOrWhiteSpace($fingerprint) -or [string]$cache.CatalogFingerprint -ne $fingerprint) { return $false }
        $flags = @($cache.InstalledFlags)
        if ($flags.Count -ne $script:SoftwareCatalog.Count) { return $false }
        $records = @($cache.Inventory)
        if ($records.Count -gt 20000) { return $false }
        for ($index = 0; $index -lt $script:SoftwareCatalog.Count; $index++) {
            $script:SoftwareCatalog[$index].IsInstalled = [bool]$flags[$index]
        }
        foreach ($record in $records) {
            if (-not $record.PSObject.Properties['Icon']) { $record | Add-Member -NotePropertyName Icon -NotePropertyValue $null }
            else { $record.Icon = $null }
            if (-not $record.PSObject.Properties['IsUniversalInventory']) { $record | Add-Member -NotePropertyName IsUniversalInventory -NotePropertyValue $true } else { $record.IsUniversalInventory = $true }
            if (-not $record.PSObject.Properties['DetailsExpanded']) { $record | Add-Member -NotePropertyName DetailsExpanded -NotePropertyValue $false } else { $record.DetailsExpanded = $false }
            if (-not $record.PSObject.Properties['Category']) { $record | Add-Member -NotePropertyName Category -NotePropertyValue '' }
        }
        $script:InstalledScanState.Inventory = @($records)
        $script:InstalledScanState.Count = [int]$cache.Count
        $script:InstalledScanState.Ready = $true
        $script:InstalledScanState.CacheLoaded = $true
        if (-not $Quiet) {
            Write-AMRLog ("Loaded cached installed-app snapshot: {0} record(s). A background refresh has been scheduled." -f $records.Count) INFO Software
        }
        return $true
    } catch {
        if (-not $Quiet) { Write-AMRLog "Installed-app cache could not be loaded and will be rebuilt: $($_.Exception.Message)" WARNING Software }
        return $false
    }
}

function Save-AMRInstalledInventoryCache {
    try {
        $fingerprint = Get-AMRInstalledCatalogFingerprint
        if ([string]::IsNullOrWhiteSpace($fingerprint)) { return $false }
        $cachePayload = [ordered]@{
            SchemaVersion = 1
            CatalogFingerprint = $fingerprint
            SavedAtUtc = [DateTime]::UtcNow.ToString('o')
            Count = [int]$script:InstalledScanState.Count
            InstalledFlags = @($script:SoftwareCatalog | ForEach-Object { [bool]$_.IsInstalled })
            Inventory = @($script:InstalledScanState.Inventory | ForEach-Object { $_ | Select-Object * -ExcludeProperty Icon })
        }
        $json = ConvertTo-Json -InputObject $cachePayload -Depth 7
        $temporaryPath = $script:InstalledInventoryCacheFile + '.tmp'
        Set-Content -LiteralPath $temporaryPath -Value $json -Encoding UTF8 -ErrorAction Stop
        Move-Item -LiteralPath $temporaryPath -Destination $script:InstalledInventoryCacheFile -Force -ErrorAction Stop
        return $true
    } catch {
        try { if (Test-Path -LiteralPath ($script:InstalledInventoryCacheFile + '.tmp')) { Remove-Item -LiteralPath ($script:InstalledInventoryCacheFile + '.tmp') -Force -ErrorAction SilentlyContinue } } catch {}
        Write-AMRLog "Could not save installed-app cache: $($_.Exception.Message)" WARNING Software
        return $false
    }
}

# ----------------------------------------------------------
# AMR Smart Icon Engine ALPHA3 - Installed Apps Bridge
# Separate local icon worker. Existing Alpha icons are preserved.
# ----------------------------------------------------------

$script:AMRLocalAdapterSource = [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String('')
)

$script:AMRLocalCollectorSource = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))

$script:AMRLocalMergerSource = [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String('')
)

. ([scriptblock]::Create($script:AMRLocalAdapterSource))

$script:AMRLocalIconWorkerState = @{
    Started = $false
    Runspace = $null
    PowerShell = $null
    Async = $null
    Timer = $null
    RecordMap = @{}
}

function Start-AMRInstalledLocalIconRefresh {

    if ($script:AMRLocalIconWorkerState.Started) {
        return
    }

    if (-not $script:ShowInstalledOnly) {
        return
    }

    $script:AMRLocalIconWorkerState.Started = $true

    try {
        $Candidates = @(
            foreach ($Record in $script:InstalledAppsInventory) {
                if ($null -eq $Record.Icon) {
                    $Record
                }
            }
        )

        if ($Candidates.Count -eq 0) {
            $script:AMRLocalIconWorkerState.Started = $false
            Write-AMRLog 'Local icon engine: no installed records require local icons.' INFO Software
            return
        }

        $Apps = @(ConvertTo-AMRShowInstalledApp -Inventory $Candidates)

        $RecordMap = @{}

        foreach ($Record in $Candidates) {
            $SafeId = Get-AMRShowInstalledSafeId -Record $Record

            if (-not [string]::IsNullOrWhiteSpace($SafeId)) {
                if (-not $RecordMap.ContainsKey($SafeId)) {
                    $RecordMap[$SafeId] = $Record
                }
            }
        }

        $Apps = @(
            foreach ($App in $Apps) {
                if ($RecordMap.ContainsKey([string]$App.AppId)) {
                    $App
                }
            }
        )

        if ($Apps.Count -eq 0) {
            $script:AMRLocalIconWorkerState.Started = $false
            Write-AMRLog 'Local icon engine: adapter returned no eligible records.' INFO Software
            return
        }

        $CachePath = Join-Path $script:IconDir 'LocalInstalled'
        $CatalogPath = Join-Path $CachePath 'UnifiedIconCatalog.json'

        $Worker = {
            param(
                [object[]]$WorkerApps,
                [string]$WorkerCachePath,
                [string]$WorkerCatalogPath,
                [string]$CollectorSource,
                [string]$MergerSource
            )

            . ([scriptblock]::Create($CollectorSource))
            . ([scriptblock]::Create($MergerSource))

            $Collection = @(
                Invoke-AMRLocalIconCollection `
                    -Apps $WorkerApps `
                    -CachePath $WorkerCachePath
            )

            $Catalog = New-AMRUnifiedIconCatalog `
                -Apps $WorkerApps `
                -CollectionResults $Collection `
                -OutputPath $WorkerCatalogPath

            return @($Catalog.Entries)
        }

        $Runspace = [RunspaceFactory]::CreateRunspace()
        $Runspace.ApartmentState = [Threading.ApartmentState]::MTA
        $Runspace.ThreadOptions = [Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
        $Runspace.Open()

        $PowerShell = [PowerShell]::Create()
        $PowerShell.Runspace = $Runspace

        [void]$PowerShell.AddScript($Worker.ToString())
        [void]$PowerShell.AddArgument($Apps)
        [void]$PowerShell.AddArgument($CachePath)
        [void]$PowerShell.AddArgument($CatalogPath)
        [void]$PowerShell.AddArgument($script:AMRLocalCollectorSource)
        [void]$PowerShell.AddArgument($script:AMRLocalMergerSource)

        $Async = $PowerShell.BeginInvoke()

        $script:AMRLocalIconWorkerState.Runspace = $Runspace
        $script:AMRLocalIconWorkerState.PowerShell = $PowerShell
        $script:AMRLocalIconWorkerState.Async = $Async
        $script:AMRLocalIconWorkerState.RecordMap = $RecordMap

        $Timer = New-Object System.Windows.Threading.DispatcherTimer
        $Timer.Interval = [TimeSpan]::FromMilliseconds(150)

        $Timer.Add_Tick({

            $State = $script:AMRLocalIconWorkerState

            if (-not $State.Async -or -not $State.Async.IsCompleted) {
                return
            }

            $State.Timer.Stop()

            try {
                $Entries = @($State.PowerShell.EndInvoke($State.Async))

                if ($script:ShowInstalledOnly) {

                    foreach ($Entry in $Entries) {

                        if (
                            $Entry.Status -ne 'Available' -or
                            $Entry.SelectedSource -ne 'LocalInstalledApp' -or
                            [string]::IsNullOrWhiteSpace([string]$Entry.IconPath)
                        ) {
                            continue
                        }

                        $AppId = [string]$Entry.AppId

                        if (-not $State.RecordMap.ContainsKey($AppId)) {
                            continue
                        }

                        $Record = $State.RecordMap[$AppId]

                        if ($null -eq $Record -or $null -ne $Record.Icon) {
                            continue
                        }

                        $StillVisible = $false

                        foreach ($CurrentRecord in $script:InstalledAppsInventory) {
                            if ([object]::ReferenceEquals($CurrentRecord,$Record)) {
                                $StillVisible = $true
                                break
                            }
                        }

                        if (-not $StillVisible) {
                            continue
                        }

                        $ImageSource = Get-AMRIconImageSource -Path ([string]$Entry.IconPath)

                        if ($null -ne $ImageSource -and $null -eq $Record.Icon) {
                            $Record.Icon = $ImageSource
                            Sync-AMRRealizedSoftwareIconItem -Item $Record
                        }
                    }
                }

                $AvailableCount = @(
                    $Entries | Where-Object {
                        $_.Status -eq 'Available' -and
                        $_.SelectedSource -eq 'LocalInstalledApp'
                    }
                ).Count

                Write-AMRLog (
                    'Local icon engine completed. Records: {0}; local icons available: {1}.' -f
                    $Entries.Count,$AvailableCount
                ) INFO Software
            }
            catch {
                Write-AMRLog "Local icon worker completion failed: $($_.Exception.Message)" WARNING Software
            }
            finally {
                try { $State.PowerShell.Dispose() } catch {}
                try { $State.Runspace.Close() } catch {}
                try { $State.Runspace.Dispose() } catch {}

                $State.PowerShell = $null
                $State.Runspace = $null
                $State.Async = $null
                $State.Timer = $null
                $State.Started = $false
            }
        })

        $script:AMRLocalIconWorkerState.Timer = $Timer
        $Timer.Start()

        Write-AMRLog (
            'Local icon engine started in background for {0} installed record(s).' -f $Apps.Count
        ) INFO Software
    }
    catch {
        $script:AMRLocalIconWorkerState.Started = $false
        Write-AMRLog "Could not start local icon engine: $($_.Exception.Message)" WARNING Software
    }
}

# V14: preserve the original catalog categories in Show Installed, map installed
# records to catalog categories in O(n), and keep installed cards compact/expandable.
function Set-AMRInstalledViewVisible {
    param([int]$InstalledCount)

    $script:ShowInstalledOnly = $true
    $InstalledCount = @($script:InstalledScanState.Inventory).Count
    $script:InstalledAppsInventory.Clear()

    # Build lookup tables once. The previous nested catalog scan was O(installed x catalog)
    # on the UI thread and caused a long pause when Show Installed contained many records.
    $catalogById = @{}
    $catalogByName = @{}
    foreach ($catalogApp in $script:SoftwareCatalog) {
        $catalogId = [string]$catalogApp.Id
        if ($catalogId) { $catalogById[$catalogId.ToLowerInvariant()] = $catalogApp }
        $catalogName = ([string]$catalogApp.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
        if ($catalogName -and -not $catalogByName.ContainsKey($catalogName)) { $catalogByName[$catalogName] = $catalogApp }
    }
    foreach ($record in @($script:InstalledScanState.Inventory)) {
        $record.IsUniversalInventory = $true
        $record.DetailsExpanded = $false
        $record.Category = ''
        $copyablePath = if (-not [string]::IsNullOrWhiteSpace([string]$record.InstallLocation)) { [string]$record.InstallLocation } elseif (-not [string]::IsNullOrWhiteSpace([string]$record.PortableRootFolder)) { [string]$record.PortableRootFolder } elseif (-not [string]::IsNullOrWhiteSpace([string]$record.PortableExecutablePath)) { [string]$record.PortableExecutablePath } elseif (-not [string]::IsNullOrWhiteSpace([string]$record.PackageFamilyName)) { [string]$record.PackageFamilyName } else { '' }
        $record.HasCopyableInstallPath = -not [string]::IsNullOrWhiteSpace($copyablePath)
        $record.DisplayInstallPath = if ($record.HasCopyableInstallPath) { $copyablePath } else { 'Not recorded by Windows' }
        $recordNorm = ([string]$record.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
        $match = $null
        $recordId = [string]$record.Id
        if ($recordId -and $catalogById.ContainsKey($recordId.ToLowerInvariant())) { $match = $catalogById[$recordId.ToLowerInvariant()] }
        elseif ($recordNorm -and $catalogByName.ContainsKey($recordNorm)) { $match = $catalogByName[$recordNorm] }
        if ($null -ne $match) {
            $record.IsCatalogApp = $true
            $record.CatalogId = [string]$match.Id
            $record.Category = [string]$match.Category
            if ($null -eq $record.Icon) { $record.Icon = $match.Icon }
        }
        [void]$script:InstalledAppsInventory.Add($record)
    }
    $script:InstalledAppsView = [System.Windows.Data.CollectionViewSource]::GetDefaultView($script:InstalledAppsInventory)
    $script:SelectedSoftwareCategory = 'All Applications'
    $script:InstalledAppsView.Filter = [System.Predicate[object]]{ param($item)
        $selectedCategory = [string]$script:SelectedSoftwareCategory
        if ($selectedCategory -and $selectedCategory -ne 'All Applications' -and [string]$item.Category -ne $selectedCategory) { return $false }
        $searchText = (C 'SearchBox').Text
        if ([string]::IsNullOrWhiteSpace($searchText)) { return $true }
        $escaped = [regex]::Escape($searchText)
        return ([string]$item.Name -match "(?i)$escaped") -or ([string]$item.Id -match "(?i)$escaped") -or ([string]$item.Publisher -match "(?i)$escaped")
    }
    (C 'SoftwareCategoryList').ItemsSource = $script:SoftwareCategories
    (C 'SoftwareCategoryList').SelectedIndex = 0
    Update-AMRSoftwareCategoryCounts
    Reset-AMRSoftwareGridPages -View $script:InstalledAppsView
    Start-AMRInstalledLocalIconRefresh
    (C 'ShowInstalledBtn').Content = "Show All ($InstalledCount)"
    (C 'ShowInstalledBtn').ToolTip = 'Return to the full software catalog.'
    (C 'ShowInstalledBtn').IsEnabled = $true
    (C 'UninstallSelectedBtn').Visibility = 'Visible'
    Write-AMRLog "Universal installed inventory displayed: $InstalledCount record(s)." INFO Software
}

function Complete-AMRInstalledCatalogScan {
    param($JobState)

    $job = $JobState.Current
    if (-not $job) { return }

    $outputItems = @()
    $workerError = ''
    try {
        $outputItems = @($job.PowerShell.EndInvoke($job.AsyncResult))
    } catch {
        $workerError = $_.Exception.Message
    }

    if (-not $workerError -and $job.PowerShell.Streams.Error.Count -gt 0) {
        $workerError = (($job.PowerShell.Streams.Error | ForEach-Object { $_.ToString() }) -join "`n")
    }

    $payload = $null
    foreach ($outputItem in $outputItems) {
        if ($null -ne $outputItem -and $outputItem.PSObject.Properties['InstalledFlags']) {
            $payload = $outputItem
        }
    }
    if (-not $payload -and -not $workerError) {
        $workerError = 'The background inventory worker completed without returning a valid result.'
    }

    try { $job.PowerShell.Dispose() } catch {}
    try { $job.Runspace.Close(); $job.Runspace.Dispose() } catch {}
    $JobState.Current = $null

    if ($payload -and -not $workerError) {
        $flags = @($payload.InstalledFlags)
        if ($flags.Count -ne $script:SoftwareCatalog.Count) {
            $workerError = "Inventory result size mismatch. Expected $($script:SoftwareCatalog.Count), received $($flags.Count)."
        } else {
            for ($index = 0; $index -lt $script:SoftwareCatalog.Count; $index++) {
                $script:SoftwareCatalog[$index].IsInstalled = [bool]$flags[$index]
            }

            # Catalog cards use PSCustomObject records, so refresh the visible
            # catalog after the background scan to re-evaluate IsInstalled bindings.
            # Preserve the current scroll position, category, search text and filters.
            if (-not $script:ShowInstalledOnly -and $script:AppsView) {
                try {
                    $softwareScroll = C 'SoftwareScrollViewer'
                    $savedScrollOffset = [double]$softwareScroll.VerticalOffset
                    $script:AppsView.Refresh()
                    Reset-AMRSoftwareGridPages -View $script:AppsView
                    $softwareScroll.UpdateLayout()
                    $softwareScroll.ScrollToVerticalOffset($savedScrollOffset)
                } catch {
                    Write-AMRLog "Could not refresh installed indicators in the software catalog: $($_.Exception.Message)" WARNING Software
                }
            }

            $JobState.Ready = $true
            $JobState.Count = [int]$payload.Count
            $JobState.Inventory = @($payload.Inventory)
            $JobState.Error = ''
            [void](Save-AMRInstalledInventoryCache)

            # If the user opened the cached Installed view while refresh was still
            # running, replace its records with the fresh snapshot without losing
            # the selected category, search text, or current scroll position.
            if ($script:ShowInstalledOnly -and $script:InstalledAppsView) {
                try {
                    $savedInstalledCategory = [string]$script:SelectedSoftwareCategory
                    $installedScroll = C 'SoftwareScrollViewer'
                    $savedInstalledOffset = [double]$installedScroll.VerticalOffset
                    Set-AMRInstalledViewVisible -InstalledCount $JobState.Count
                    if ($savedInstalledCategory -and $savedInstalledCategory -ne 'All Applications') {
                        $categoryItem = @($script:SoftwareCategories | Where-Object { [string]$_.Name -eq $savedInstalledCategory } | Select-Object -First 1)
                        if ($categoryItem.Count -gt 0) { (C 'SoftwareCategoryList').SelectedItem = $categoryItem[0] }
                    }
                    $installedScroll.UpdateLayout()
                    $installedScroll.ScrollToVerticalOffset($savedInstalledOffset)
                } catch {
                    Write-AMRLog "Could not refresh the visible Installed view from the new snapshot: $($_.Exception.Message)" WARNING Software
                }
            }
            foreach ($entry in @($payload.Logs)) {
                if ($entry -and $entry.Message) {
                    $level = if ($entry.Level) { [string]$entry.Level } else { 'INFO' }
                    $area = if ($entry.Area) { [string]$entry.Area } else { 'Software' }
                    Write-AMRLog ([string]$entry.Message) $level $area
                }
            }
        }
    }

    if ($workerError) {
        # Keep a previously loaded/completed snapshot usable if only the refresh failed.
        # A first-run failure still leaves Ready=false and reports the error normally.
        $JobState.Error = $workerError
        Write-AMRLog "Background installed-app scan failed: $workerError" ERROR Software
        if ($JobState.PendingShow) {
            (C 'ShowInstalledBtn').Content = 'Show Installed'
            (C 'ShowInstalledBtn').IsEnabled = $true
            $JobState.PendingShow = $false
            Show-AMRMessage "Could not finish the installed-app scan:`n`n$workerError" 'Installed Apps Scan' OK Error | Out-Null
        }
    }

    # If a refresh was requested while an older scan was running (for example,
    # immediately after uninstall), run a fresh scan before publishing the view.
    if ($JobState.RescanRequested) {
        $JobState.RescanRequested = $false
        $JobState.Ready = $false
        Start-AMRInstalledCatalogScan -ShowWhenReady:([bool]$JobState.PendingShow)
        return
    }

    if ($JobState.Ready -and $JobState.PendingShow) {
        $JobState.PendingShow = $false
        Set-AMRInstalledViewVisible -InstalledCount $JobState.Count
    }
}

function Start-AMRInstalledCatalogScan {
    param(
        [switch]$ShowWhenReady,
        [switch]$Refresh
    )

    $state = $script:InstalledScanState
    if ($ShowWhenReady) { $state.PendingShow = $true }

    if ($state.Current) {
        if ($Refresh) { $state.RescanRequested = $true }
        return
    }

    if ($state.Ready -and -not $Refresh) {
        if ($state.PendingShow) {
            $state.PendingShow = $false
            Set-AMRInstalledViewVisible -InstalledCount $state.Count
        }
        return
    }

    $catalogSnapshot = @(
        foreach ($app in $script:SoftwareCatalog) {
            [pscustomobject]@{
                Name = [string]$app.Name
                Id = [string]$app.Id
                ChocoId = [string]$app.ChocoId
                IsInstalled = $false
            }
        }
    )

    try {
        $inventoryCommand = Get-Command Update-AMRInstalledCatalogState -ErrorAction Stop
        $inventoryFunctionBody = $inventoryCommand.ScriptBlock.ToString()
        $matchCommand = Get-Command Set-AMRInstalledCatalogMatches -ErrorAction Stop
        $matchFunctionBody = $matchCommand.ScriptBlock.ToString()
        $universalCommand = Get-Command Get-AMRUniversalInstalledInventory -ErrorAction Stop
        $universalFunctionBody = $universalCommand.ScriptBlock.ToString()
        $recordCommand = Get-Command New-AMRInstalledInventoryRecord -ErrorAction Stop
        $recordFunctionBody = $recordCommand.ScriptBlock.ToString()

        $workerScript = @'
param($CatalogSnapshot, $InventoryFunctionBody, $MatchFunctionBody, $UniversalFunctionBody, $RecordFunctionBody)
$ErrorActionPreference = 'Continue'
$script:SoftwareCatalog = @($CatalogSnapshot)
$script:InventoryLogs = New-Object 'System.Collections.Generic.List[object]'
function Write-AMRLog {
    param([string]$Message, [string]$Level, [string]$Area)
    try {
        [void]$script:InventoryLogs.Add([pscustomobject]@{
            Message = [string]$Message
            Level = [string]$Level
            Area = [string]$Area
        })
    } catch {}
}
$matchDefinition = "function Set-AMRInstalledCatalogMatches {`r`n" + $MatchFunctionBody + "`r`n}"
Invoke-Expression $matchDefinition
$definition = "function Update-AMRInstalledCatalogState {`r`n" + $InventoryFunctionBody + "`r`n}"
Invoke-Expression $definition
$recordDefinition = "function New-AMRInstalledInventoryRecord {`r`n" + $RecordFunctionBody + "`r`n}"
Invoke-Expression $recordDefinition
$universalDefinition = "function Get-AMRUniversalInstalledInventory {`r`n" + $UniversalFunctionBody + "`r`n}"
Invoke-Expression $universalDefinition
$scanResult = Update-AMRInstalledCatalogState
$flags = @($script:SoftwareCatalog | ForEach-Object { [bool]$_.IsInstalled })
# Reuse the WinGet output collected above; do not launch a second WinGet CLI scan.
$inventory = @(Get-AMRUniversalInstalledInventory -WingetRawOutput ([string]$scanResult.WingetRawOutput) -SkipWingetScan)
[pscustomobject]@{
    Count = [int]$scanResult.Count
    InstalledFlags = $flags
    Inventory = $inventory
    Logs = @($script:InventoryLogs.ToArray())
}
'@

        $runspace = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
        $runspace.Open()
        $powerShell = [PowerShell]::Create()
        $powerShell.Runspace = $runspace
        [void]$powerShell.AddScript($workerScript)
        [void]$powerShell.AddArgument($catalogSnapshot)
        [void]$powerShell.AddArgument($inventoryFunctionBody)
        [void]$powerShell.AddArgument($matchFunctionBody)
        [void]$powerShell.AddArgument($universalFunctionBody)
        [void]$powerShell.AddArgument($recordFunctionBody)
        $asyncResult = $powerShell.BeginInvoke()

        $timer = New-Object System.Windows.Threading.DispatcherTimer
        $timer.Interval = [TimeSpan]::FromMilliseconds(150)
        $jobState = $state
        $job = [pscustomobject]@{
            PowerShell = $powerShell
            Runspace = $runspace
            AsyncResult = $asyncResult
            Timer = $timer
        }
        $state.Current = $job

        $timer.Add_Tick({
            $activeJob = $jobState.Current
            if (-not $activeJob) {
                $timer.Stop()
                return
            }
            if (-not $activeJob.AsyncResult.IsCompleted) { return }
            $timer.Stop()
            Complete-AMRInstalledCatalogScan -JobState $jobState
        }.GetNewClosure())

        $timer.Start()
        Write-AMRLog 'Installed-app inventory scan started in the background. The interface remains available.' INFO Software
    } catch {
        $state.Error = $_.Exception.Message
        $state.Ready = $false
        $state.Current = $null
        (C 'ShowInstalledBtn').Content = 'Show Installed'
        (C 'ShowInstalledBtn').IsEnabled = $true
        Write-AMRLog "Could not start the background installed-app scan: $($_.Exception.Message)" ERROR Software
        if ($state.PendingShow) {
            $state.PendingShow = $false
            Show-AMRMessage "Could not start the installed-app scan:`n`n$($_.Exception.Message)" 'Installed Apps Scan' OK Error | Out-Null
        }
    }
}

$script:AppsView.Filter = [System.Predicate[object]]{
    param($item)
    if ($script:ShowInstalledOnly -and -not $item.IsInstalled) { return $false }

    $selectedCategory = [string]$script:SelectedSoftwareCategory
    if (-not [string]::IsNullOrWhiteSpace($selectedCategory) -and
        $selectedCategory -ne 'All Applications' -and
        [string]$item.Category -ne $selectedCategory) { return $false }

    $searchText = (C 'SearchBox').Text
    if ([string]::IsNullOrWhiteSpace($searchText)) { return $true }
    $escaped = [regex]::Escape($searchText)
    return ($item.Name -match "(?i)$escaped") -or ($item.Id -match "(?i)$escaped")
}

# Keep the existing four-column UniformGrid and card template. Populate the
# grid incrementally so opening Software does not create the full catalog at once.
# Note: the standard ItemsControl/UniformGrid remains non-virtualized; paging only
# limits the number of cards currently added to the visual tree.
$script:SoftwareGridPageItems = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
$script:SoftwareGridPageSource = @()
$script:SoftwareGridPageIndex = 0
$script:SoftwareGridPageSize = 16
$script:SoftwareGridPageBusy = $false
$script:SoftwareGridPageDispatchPending = $false

function Add-AMRSoftwareGridPage {
    if ($script:SoftwareGridPageBusy) { return }

    $script:SoftwareGridPageBusy = $true

    try {
        $end = [Math]::Min(
            $script:SoftwareGridPageIndex + $script:SoftwareGridPageSize,
            $script:SoftwareGridPageSource.Count
        )

        while ($script:SoftwareGridPageIndex -lt $end) {
            [void]$script:SoftwareGridPageItems.Add(
                $script:SoftwareGridPageSource[$script:SoftwareGridPageIndex]
            )
            $script:SoftwareGridPageIndex++
        }
    } finally {
        $script:SoftwareGridPageBusy = $false
    }

    Queue-AMRSoftwareIconSync
}

function Reset-AMRSoftwareGridPages {
    param([Parameter(Mandatory=$true)]$View)

    # Prepare the replacement page off-screen, then swap ItemsSource once.
    # Clearing the bound ObservableCollection first forces WPF to destroy every
    # realized card and leaves the Software surface visibly empty during resize.
    $newSoftwareGridPageItems = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
    $script:SoftwareGridPageIndex = 0

    # Build a stable category sequence: all applications from one category stay
    # together, preserving their original order inside that category. This
    # prevents separators from jumping backwards (e.g. 2, 1, 3, 2).
    $viewItems = @($View)
    $columns = 4 # Keep exactly four application cards per row in every window state.
    $orderedItems = New-Object 'System.Collections.Generic.List[object]'
    $categoryOrdinals = @{}
    for ($categoryIndex = 0; $categoryIndex -lt $script:SoftwareCategoryNames.Count; $categoryIndex++) {
        $categoryName = [string]$script:SoftwareCategoryNames[$categoryIndex]
        $categoryOrdinals[$categoryName] = [int]($categoryIndex + 1)
    }

    $groupIndex = 0
    foreach ($categoryName in $script:SoftwareCategoryNames) {
        $groupItems = @($viewItems | Where-Object { [string]$_.Category -eq [string]$categoryName })
        if ($groupItems.Count -eq 0) { continue }

        # Pad to the first column before each new category. The hidden cells
        # reserve UniformGrid positions so every blue separator shares one X axis.
        if ($groupIndex -gt 0) {
            $remainder = $orderedItems.Count % $columns
            if ($remainder -ne 0) {
                $padCount = $columns - $remainder
                for ($pad = 0; $pad -lt $padCount; $pad++) {
                    $spacer = [pscustomobject]@{ IsCategorySpacer = $true; IsCategoryStart = $false; IsCategoryHeaderRow = $false; CategoryNumber = ''; Category = ''; Icon = $null; Initials = '' }
                    [void]$orderedItems.Add($spacer)
                }
            }
        }

        $ordinal = [int]$categoryOrdinals[[string]$categoryName]
        $firstInGroup = $true
        $appIndexInGroup = 0
        foreach ($app in $groupItems) {
            foreach ($propertyName in @('IsCategorySpacer','IsCategoryStart','IsCategoryHeaderRow','CategoryNumber')) {
                if (-not $app.PSObject.Properties[$propertyName]) {
                    $app | Add-Member -NotePropertyName $propertyName -NotePropertyValue $null
                }
            }
            # Category 1 is the initial All Applications section: deliberately
            # no numbered marker is shown before it.
            $app.IsCategorySpacer = $false
            $app.IsCategoryStart = [bool]($firstInGroup -and $ordinal -gt 1)
            # All cards in the category's first grid row reserve the same header gap.
            # This keeps the separator spacing continuous across columns without shifting later rows.
            $app.IsCategoryHeaderRow = [bool]($ordinal -gt 1 -and $appIndexInGroup -lt $columns)
            $app.CategoryNumber = if ($ordinal -gt 1) { [string]$ordinal } else { '' }
            [void]$orderedItems.Add($app)
            $firstInGroup = $false
            $appIndexInGroup++
        }
        $groupIndex++
    }

    # Keep any uncategorized entries at the end without introducing fake numbers.
    $uncategorized = @($viewItems | Where-Object { [string]::IsNullOrWhiteSpace([string]$_.Category) })
    foreach ($app in $uncategorized) {
        foreach ($propertyName in @('IsCategorySpacer','IsCategoryStart','IsCategoryHeaderRow','CategoryNumber')) {
            if (-not $app.PSObject.Properties[$propertyName]) { $app | Add-Member -NotePropertyName $propertyName -NotePropertyValue $null }
        }
        $app.IsCategorySpacer = $false
        $app.IsCategoryStart = $false
        $app.IsCategoryHeaderRow = $false
        $app.CategoryNumber = ''
        [void]$orderedItems.Add($app)
    }

    $script:SoftwareGridPageSource = $orderedItems.ToArray()
    # Keep the visual tree deliberately small on every launch. A UniformGrid
    # inside a regular ScrollViewer is NOT virtualized, so add a small first batch.
    $script:SoftwareGridPageSize = 16
    # Prefill complete four-card rows to avoid a partially populated row on first display.
    $initialCount = if ($script:Window.WindowState -eq [System.Windows.WindowState]::Maximized) { 48 } else { 16 }
    $initialEnd = [Math]::Min($initialCount, $script:SoftwareGridPageSource.Count)
    while ($script:SoftwareGridPageIndex -lt $initialEnd) {
        [void]$newSoftwareGridPageItems.Add($script:SoftwareGridPageSource[$script:SoftwareGridPageIndex])
        $script:SoftwareGridPageIndex++
    }
    # Commit the completed collection in one UI operation. This avoids the
    # empty-grid flash and repeated visual-tree teardown during maximize/restore.
    $script:SoftwareGridPageItems = $newSoftwareGridPageItems
    try {
        (C 'SoftwareGrid').ItemsSource = $script:SoftwareGridPageItems
        Queue-AMRSoftwareIconSync
        (C 'SoftwareScrollViewer').ScrollToTop()
    } catch {}
}


